  <main class="shell">
    <section class="quiz-card">
      <div class="eyebrow">Interactive quiz</div>
      <h1>Computer Languages Quiz</h1>
      <p class="intro">
        Test your knowledge across systems, JVM, and declarative languages. Each question allows multiple selections.
      </p>

      <form id="quiz-form">
        <div class="form-field">
          <fieldset>
            <legend class="question-label">1. Which languages are commonly used for systems programming?</legend>
            <p class="help-text">Select every answer that fits. More than one option is correct.</p>
            <div class="choices">
              <label class="choice"><input type="checkbox" name="q1" value="C"><span>C</span></label>
              <label class="choice"><input type="checkbox" name="q1" value="Rust"><span>Rust</span></label>
              <label class="choice"><input type="checkbox" name="q1" value="Python"><span>Python</span></label>
              <label class="choice"><input type="checkbox" name="q1" value="Ruby"><span>Ruby</span></label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend class="question-label">2. Which languages typically compile to JVM bytecode?</legend>
            <div class="choices">
