              <label class="choice"><input type="checkbox" name="q2" value="Kotlin"><span>Kotlin</span></label>
              <label class="choice"><input type="checkbox" name="q2" value="C++"><span>C++</span></label>
              <label class="choice"><input type="checkbox" name="q2" value="Swift"><span>Swift</span></label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend class="question-label">3. Which of these are primarily declarative or query languages?</legend>
            <div class="choices">
              <label class="choice"><input type="checkbox" name="q3" value="SQL"><span>SQL</span></label>
              <label class="choice"><input type="checkbox" name="q3" value="GraphQL"><span>GraphQL</span></label>
              <label class="choice"><input type="checkbox" name="q3" value="Go"><span>Go</span></label>
              <label class="choice"><input type="checkbox" name="q3" value="JavaScript"><span>JavaScript</span></label>
            </div>
