     const result = document.getElementById("result");

     const answerKey = {
       q1: ["C", "Rust"],
       q2: ["Java", "Kotlin"],
       q3: ["SQL", "GraphQL"]
     };

     function getSelectedValues(name) {
       return Array.from(form.querySelectorAll(`input[name="${name}"]:checked`))
         .map((input) => input.value)
         .sort();
     }

     function isCorrect(questionName) {
       const selected = getSelectedValues(questionName);
       const expected = [...answerKey[questionName]].sort();

       return selected.length === expected.length &&
         selected.every((value, index) => value === expected[index]);
     }

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const totalQuestions = Object.keys(answerKey).length;
       const score = Object.keys(answerKey).filter(isCorrect).length;

       result.textContent = `You scored ${score} out of ${totalQuestions}.`;
       result.classList.add("is-visible");
     });
